import{z as n,x as o,o as B,c as C,q as r,j as s,D as e,d as A,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"性能与成本的联合优化案例","description":"","frontmatter":{"title":"性能与成本的联合优化案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-cost-case.md","filePath":"cs/pe3-cost-case.md","lastUpdated":1791063341000}'),p={name:"cs/pe3-cost-case.md"};function D(d,E,m,F,c,h){const t=o("Mermaid");return B(),C("div",null,[E[2]||(E[2]=r('<h1 id="性能与成本的联合优化案例" tabindex="-1">性能与成本的联合优化案例 <a class="header-anchor" href="#性能与成本的联合优化案例" aria-label="Permalink to &quot;性能与成本的联合优化案例&quot;">​</a></h1><div class="epigraph"><p>SLO 是约束，成本是目标函数；只优化任何一边的团队，都是在另一边的账本上偷偷透支。</p><footer>—— 据 Barroso 与 Hölzle，The Datacenter as a Computer，2nd ed., 2018 与 Beyer 等，Site Reliability Engineering，2016 口径整理</footer></div><p><a href="/cs/pe3-tail-latency-case">上一课</a>把 p99 收回错误预算内，大促平稳落地。本课程最后一类案例处理剩下的那对张力：性能达标之后，账单怎么办。季度复盘时这个服务的月账单超预算四成——性能与成本在两份报表里分开记账，没有人同时看两本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>性能团队的安全水位、成本团队的缩减计划互相看不见：前者为峰值买的 N+2 冗余，在后者眼里是常年闲置；后者砍掉的「低价值」缓存，正是前者刚修好的尾延迟的支柱。缺口不是哪个单方的技术，而是把两本账合成一本：<strong>在 SLO 约束下最小化单位成本</strong>。不这么做会错在哪：先做性能再谈成本，结果过度供给成为常态——没人记得冗余是应急保险还是永久开销；或者反过来先省钱，砍缓存、抬水位，把刚攒下的延迟余量一次性花光，下一轮回归直接烧穿预算。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，建每请求成本账。把账单摊到请求上：CPU 秒、内存 GB·时、出流量、跨区流量、以及每一次下游调用——缓存 miss 就是一次付费的下游调用。账单是聚合的，杠杆藏在分母里；没有单位成本的优化无法排序。</p><p>第二步，找大户与它们的杠杆。出流量与跨区复制常是第一大户，CPU 未必。杠杆用 Amdahl 的钱版本：优化占账单 5% 的项，全省也只有 5%。优先扫「双赢点」——性能与成本同向的地方：缓存命中率从 0.90 提到 0.95，回源量沿 \\(1-h\\) 减半，下游费用与回源延迟同时减半；这类点先做，做完再谈取舍。</p><p><span class="marginnote">数字实例（命中率的杠杆）：回源量正比于 \\(1-h\\)。命中率 0.90 时每 100 个请求有 10 个回源；提到 0.95 只剩 5 个——账面上命中率只涨 5 个百分点，回源费用和回源延迟却都直接减半。命中率越高的区间，每提高一点值钱越多，这和直觉刚好相反。</span></p><p>第三步，在 SLO 约束下重新定价余量。安全水位从「固定七成」变成「SLO 允许的最高水位」：<a href="/cs/pe3-requirements">第一课</a>的错误预算是可以花的钱，水位每抬高一个点，都要在分位上验收——风险不是均值变差，是变异变大、尾先动（上一课的账）。延迟不敏感的批任务挪到低价时段或可抢占实例，与在线负载隔离，隔离的代价计回成本账一起算。</p><p>第四步，验收与性能优化同一套协议：灰度、分位对账、可回滚。成本优化降低的每一块钱都要能指认它对应的性能风险敞口。</p>',11)),(B(),s(i,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BILL%5B%22%E8%B4%A6%E5%8D%95%E8%B6%85%E9%A2%84%E7%AE%97%2040%25%22%5D%20--%3E%20UNIT%5B%22%E5%BB%BA%E6%AF%8F%E8%AF%B7%E6%B1%82%E6%88%90%E6%9C%AC%E8%B4%A6%22%5D%0A%20%20UNIT%20--%3E%20TOP%5B%22%E6%89%BE%E5%A4%A7%E6%88%B7%E4%B8%8E%E6%9D%A0%E6%9D%86%EF%BC%9A%E6%B5%81%E9%87%8F%E3%80%81%E5%9B%9E%E6%BA%90%E3%80%81CPU%22%5D%0A%20%20TOP%20--%3E%20WIN%5B%22%E5%8F%8C%E8%B5%A2%E7%82%B9%E4%BC%98%E5%85%88%EF%BC%9A%E5%91%BD%E4%B8%AD%E7%8E%87%E3%80%81%E6%89%B9%E4%BB%BB%E5%8A%A1%E6%8C%AA%E5%B3%B0%22%5D%0A%20%20WIN%20--%3E%20RAISE%5B%22SLO%20%E7%BA%A6%E6%9D%9F%E4%B8%8B%E6%8A%AC%E5%AE%89%E5%85%A8%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20RAISE%20--%3E%20VERI%7B%22%E5%88%86%E4%BD%8D%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%B0%BE%E6%9C%AA%E5%8A%A8%22%7D%0A%20%20VERI%20--%3E%7C%22%E5%B0%BE%E5%8A%A8%E4%BA%86%22%7C%20BACK%5B%22%E9%80%80%E5%9B%9E%E6%B0%B4%E4%BD%8D%EF%BC%8C%E9%87%8D%E9%80%89%E6%9D%A0%E6%9D%86%22%5D%0A%20%20VERI%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20DONE%5B%22%E7%BB%93%E6%A1%88%EF%BC%9A%E6%88%90%E6%9C%AC%E8%B4%A6%E8%BF%9B%E7%9C%8B%E6%9D%BF%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"每请求成本为什么是正确的分母：它把「买多大」与「跑多快」放进同一量纲——每请求成本等于单价乘资源占用除以有效吞吐，缓存与批处理改变分母（吞吐），压缩改变分子（资源），摊平了才能比较。命中率为什么是指数杠杆：回源量正比于 \\(1-h\\)，h 从 0.90 到 0.95 在绝对数上只有五个百分点，在回源侧却是减半——在命中率高的区间优化它，性价比远高于在 CPU 上再挤 10%。水位与预算为什么必须联动：容量课的六到七成水位是按「模型有误差」定价的保险；当监控积累足够、模型误差收窄，保险可以降价——但降价幅度由错误预算付账，不由账单付账。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"本案例最大的单项节省不在任何 CPU 报表里：聚合结果的跨区读改成本区读加索引同步，账单降两成而延迟不变。云账单里「数据搬运」一项经常大于计算一项——按资源类型而不是按服务维度看账单，才能看见这类钱。")],-1)),(B(),s(i,null,{default:e(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%E4%BC%98%E5%8C%96%E9%A1%B9%22%5D%20--%3E%20SHARE%7B%22%E5%8D%A0%E8%B4%A6%E5%8D%95%E6%AF%94%E4%BE%8B%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20SHARE%20--%3E%7C%22%E5%B0%8F%E4%BA%8E%205%25%20%E7%9A%84%E8%BE%B9%E8%A7%92%22%7C%20SKIP%5B%22%E6%9D%A0%E6%9D%86%E5%A4%AA%E5%B0%8F%EF%BC%9A%E5%85%88%E6%94%BE%E4%B8%80%E8%BE%B9%22%5D%0A%20%20SHARE%20--%3E%7C%22%E5%A4%A7%E6%88%B7%22%7C%20DIR%7B%22%E6%80%A7%E8%83%BD%E4%B8%8E%E6%88%90%E6%9C%AC%E5%90%8C%E5%90%91%E5%90%97%EF%BC%9F%22%7D%0A%20%20DIR%20--%3E%7C%22%E5%90%8C%E5%90%91%EF%BC%88%E5%8F%8C%E8%B5%A2%E7%82%B9%EF%BC%89%22%7C%20DOFIRST%5B%22%E4%BC%98%E5%85%88%E5%81%9A%EF%BC%9A%E5%91%BD%E4%B8%AD%E7%B1%BB%E4%BC%98%E5%8C%96%E3%80%81%E6%8C%AA%E5%B3%B0%22%5D%0A%20%20DIR%20--%3E%7C%22%E5%8F%8D%E5%90%91%EF%BC%88%E5%8F%96%E8%88%8D%EF%BC%89%22%7C%20SLO%5B%22%E8%BF%9B%20SLO%20%E7%BA%A6%E6%9D%9F%E8%AF%84%E4%BC%B0%EF%BC%9A%E8%8A%B1%E9%94%99%E8%AF%AF%E9%A2%84%E7%AE%97%E6%8D%A2%E9%92%B1%22%5D%0A%20%20DOFIRST%20--%3E%20V%5B%22%E5%88%86%E4%BD%8D%E9%AA%8C%E6%94%B6%E5%90%8E%E7%BB%93%E6%A1%88%22%5D%0A%20%20SLO%20--%3E%20V%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>这张图回答的问题是：拿到一串候选成本优化时，先做哪个？决策只有两问——它占账单多大（Amdahl 的钱版本封死小项的天花板），以及它是否和性能同向（双赢点不需要付风险，反向取舍才要动用错误预算）。先扫完免费的同向区，再谈要付延迟风险的硬取舍。</p><p><span class="marginnote">直觉类比：「安全水位」就像买房时留的应急存款——按收入波动定价。刚开始工作没积蓄时留六个月开销；收入稳定、有历史数据后可以降成三个月。水位从七成抬到八成，就是用监控数据证明「波动其实更小」，把多余的保险退掉换现金流——退多少由错误预算（风险承受力）说了算，不由想省钱的念头说了算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单价是外生变量：云厂商调价、机型换代、汇率，都能让优化结论翻盘——成本账必须可重算，参数与公式进版本库。成本优化有重组成本：迁移、重训、冻结期，不是每次账单上涨都值得动架构。有些钱不该省：错误预算的余量、多可用区冗余、安全容量是保险不是浪费，「全都能省」的成本报告等于没做过风险管理。本课程不进财务口径（摊销、折旧、预留折扣），只到工程能控制的资源账为止；再往下是财务的账本。</p><p><span class="marginnote">为什么重要：成本账不可重算，等于优化结论无法审计——半年后云厂商降价三成，你既说不清当初省的钱还剩多少，也说不清哪个结论还成立。把单价、用量、公式存进版本库，调价时重跑一遍脚本，就知道哪些优化已经翻盘，而不是靠回忆。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>联合优化写成一个不等式：SLO 约束下最小化单位成本；两本账合成一本才有解。</li><li>每请求成本账是排序的依据；账单是聚合的，杠杆在分母里。</li><li>双赢点先做：命中率沿 \\(1-h\\) 的减半效应，性能与成本同向。</li><li>水位是保险：抬水位花的钱记在错误预算上，验收在分位不在均值。</li><li>成本账要可重算、优化要可回滚；单价一变结论就变。</li><li>出处：Barroso 与 Hölzle，<em>The Datacenter as a Computer</em>，2nd ed., 2018；Beyer 等，<em>Site Reliability Engineering</em>，2016；据本课四步口径整理。</li></ul>',7))])}const T=n(p,[["render",D]]);export{u as __pageData,T as default};
